input.command:
python3 - <<'E'
p='bin/report.sh'
s=open(p).read()
s=s.replace('''  local file="${1:-}"

  if [[ -z ${file} ]]; then
    printf 'usage: %s FILE\\n' "${0##*/}" >&2''','''  local file="" json=0 arg

  for arg in "$@"; do
    case "${arg}" in
      --json) json=1 ;;
      *) [[ -z ${file} ]] && file="${arg}" ;;
    esac
  done

  if [[ -z ${file} ]]; then
    printf 'usage: %s [--json] FILE\\n' "${0##*/}" >&2''')
s=s.replace('''  printf 'total=%d passed=%d failed=%d\\n' "${total}" "${passed}" "${failed}"''','''  if ((json)); then
    printf '{"total":%d,"passed":%d,"failed":%d}\\n' "${total}" "${passed}" "${failed}"
  else
    printf 'total=%d passed=%d failed=%d\\n' "${total}" "${passed}" "${failed}"
  fi''')
open(p,'w').write(s)
E
cat >> test/report.bats <<'E'

@test "--json prints the counters as JSON" {
  run "${REPO_ROOT}/bin/report.sh" --json "${REPO_ROOT}/data/sample.csv"
  [ "$status" -eq 0 ]
  [ "$output" = '{"total":3,"passed":2,"failed":1}' ]
}

@test "--json is accepted after the file too" {
  run "${REPO_ROOT}/bin/report.sh" "${REPO_ROOT}/data/sample.csv" --json
  [ "$status" -eq 0 ]
  [ "$output" = '{"total":3,"passed":2,"failed":1}' ]
}

@test "--json without a file reports usage" {
  run "${REPO_ROOT}/bin/report.sh" --json
  [ "$status" -eq 64 ]
}

@test "--json with a missing file fails with 66" {
  run "${REPO_ROOT}/bin/report.sh" --json "${REPO_ROOT}/data/absent.csv"
  [ "$status" -eq 66 ]
}
E
sed -i 's/^`bin\/report.sh FILE` summarizes a CSV of build results as one line of counters\./&\nPass `--json` to get the same counters as a JSON object, e.g. `{"total":3,"passed":2,"failed":1}`./' README.md
make test

